import java.sql.*;

public class JDBCBasics {
    public static void main(String[] args) throws Exception {
        // Note: H2 JDBC driver must be on classpath
        // This demonstrates the JDBC pattern
        System.out.println("JDBC pattern demonstrated");
        System.out.println("Step 1: DriverManager.getConnection(url)");
        System.out.println("Step 2: conn.prepareStatement(sql)");
        System.out.println("Step 3: stmt.executeUpdate() / executeQuery()");
        System.out.println("Step 4: rs.next() / rs.getString()");
    }
}

