import java.sql.*;

public class Transactions {
    static void transferDemo(boolean fail) {
        System.out.println("BEGIN TRANSACTION");
        try {
            System.out.println("  Debit account A");
            if (fail) throw new RuntimeException("Simulated failure");
            System.out.println("  Credit account B");
            System.out.println("COMMITTED");
        } catch (Exception e) {
            System.out.println("ROLLED BACK: " + e.getMessage());
        }
    }
    public static void main(String[] args) {
        transferDemo(false);
        transferDemo(true);
    }
}
